script:
// ph_faktura: Button „Rechnung erstellen“ (Barverkauf-Rechnung aus bezahlter Shop-Bestellung)
frappe.ui.form.on("PH Bestellung", {
	refresh(frm) {
		if (frm.is_new()) return;
		if (frm.doc.ph_faktura_rechnung) {
			frm.add_custom_button(__("Rechnung öffnen"), () => frappe.set_route("Form", "PH Rechnung", frm.doc.ph_faktura_rechnung), __("Faktura"));
			return;
		}
		if (["bezahlt", "versandbereit", "versendet", "abgeholt", "abholbereit"].includes(frm.doc.status)) {
			frm.add_custom_button(__("Rechnung erstellen"), () => {
				frappe.call({ method: "ph_faktura.api.create_cash_invoice", args: { bestellung: frm.doc.name, idempotency_key: "bestellung:" + frm.doc.name }, freeze: true }).then((r) => {
					if (r.message && r.message.rechnung) frappe.set_route("Form", "PH Rechnung", r.message.rechnung);
				});
			}, __("Faktura"));
		}
	},
});

// ph_faktura: Button „Angebot erstellen“ aus dem Projekt
frappe.ui.form.on("PH Projekt", {
	refresh(frm) {
		if (frm.is_new()) return;
		frm.add_custom_button(__("Angebot erstellen"), () => {
			frappe.new_doc("PH Angebot", { projekt: frm.doc.name, kontakt: frm.doc.kontakt, anfrage: frm.doc.anfrage });
		}, __("Faktura"));
		if (frm.doc.ph_faktura_angebot) frm.add_custom_button(__("Angebot öffnen"), () => frappe.set_route("Form", "PH Angebot", frm.doc.ph_faktura_angebot), __("Faktura"));
	},
});

// ph_faktura: Button „Mit Rechnung verknüpfen“ auf PH Zahlung (Eingang ohne Rechnungsbezug)
frappe.ui.form.on("PH Zahlung", {
	refresh(frm) {
		if (frm.is_new() || frm.doc.docstatus !== 1 || frm.doc.art !== "Eingang") return;
		if (frm.doc.ph_faktura_rechnung) {
			frm.add_custom_button(__("Rechnung öffnen"), () => frappe.set_route("Form", "PH Rechnung", frm.doc.ph_faktura_rechnung), __("Faktura"));
			return;
		}
		frm.add_custom_button(__("Mit Rechnung verknüpfen"), () => {
			frappe.prompt([{ fieldname: "rechnung", fieldtype: "Link", options: "PH Rechnung", label: __("Rechnung"), reqd: 1, get_query: () => ({ filters: { docstatus: 1, offen_cent: [">", 0] } }) }], (v) => {
				frappe.call({ method: "ph_faktura.api.register_payment", args: { rechnung: v.rechnung, betrag_cent: frm.doc.betrag_cent, kanal: frm.doc.kanal, zahlung: frm.doc.name, datum: frm.doc.zeitpunkt, idempotency_key: "zahlung:" + frm.doc.name }, freeze: true })
					.then(() => { frappe.db.set_value("PH Zahlung", frm.doc.name, "ph_faktura_rechnung", v.rechnung).then(() => frm.reload_doc()); });
			}, __("Zahlung zuordnen"), __("Verknüpfen"));
		}, __("Faktura"));
	},
});
